832  coap_pdu_parse_header(coap_pdu_t *pdu, coap_proto_t proto) {
   833    uint8_t *hdr = pdu->token - pdu->hdr_size;
   834    if (proto == COAP_PROTO_UDP || proto == COAP_PROTO_DTLS) {
   835      assert(pdu->hdr_size == 4);
   836      if ((hdr[0] >> 6) != COAP_DEFAULT_VERSION) {
   837        coap_log(LOG_DEBUG, "coap_pdu_parse: UDP version not supported\n");
   838        return 0;
   839      }
   840      pdu->type = (hdr[0] >> 4) & 0x03;
   841      pdu->token_length = hdr[0] & 0x0f;
   842      pdu->code = hdr[1];
   843      pdu->mid = (uint16_t)hdr[2] << 8 | hdr[3];
   844    } else if (proto == COAP_PROTO_TCP || proto == COAP_PROTO_TLS) {
   845      assert(pdu->hdr_size >= 2 && pdu->hdr_size <= 6);
   846      pdu->type = COAP_MESSAGE_CON;
   847      pdu->token_length = hdr[0] & 0x0f;
   848      pdu->code = hdr[pdu->hdr_size-1];
   849      pdu->mid = 0;
   850    } else {
   851      coap_log(LOG_DEBUG, "coap_pdu_parse: unsupported protocol\n");
   852      return 0;
   853    }
   854    if (pdu->token_length > pdu->alloc_size) {
   855      /* Invalid PDU provided - not wise to assert here though */
   856      coap_log(LOG_DEBUG, "coap_pdu_parse: PDU header token size broken\n");
   857      pdu->token_length = (uint8_t)pdu->alloc_size;
   858      return 0;
   859    }
   860    return 1;
   861  }
