   863  static int
   864  coap_pdu_parse_opt_csm(coap_pdu_t *pdu, uint16_t len) {
   865    switch ((coap_pdu_signaling_proto_t)pdu->code) {
   866    case COAP_SIGNALING_CSM:
   867      switch (pdu->max_opt) {
   868      case COAP_SIGNALING_OPTION_MAX_MESSAGE_SIZE:
   869        if (len > 4) goto bad;
   870        break;
   871      case COAP_SIGNALING_OPTION_BLOCK_WISE_TRANSFER:
   872        if (len > 0) goto bad;
   873        break;
   874      default:
   875        ;
   876      }
   877      break;
   878    case COAP_SIGNALING_PING:
   879    case COAP_SIGNALING_PONG:
   880      switch (pdu->max_opt) {
   881      case COAP_SIGNALING_OPTION_CUSTODY:
   882        if (len > 0) goto bad;
   883        break;
   884      default:
   885        ;
   886      }
   887      break;
   888    case COAP_SIGNALING_RELEASE:
   889      switch (pdu->max_opt) {
   890      case COAP_SIGNALING_OPTION_ALTERNATIVE_ADDRESS:
   891        if (len < 1 || len > 255) goto bad;
   892        break;
   893      case COAP_SIGNALING_OPTION_HOLD_OFF:
   894        if (len > 3) goto bad;
   895        break;
   896      default:
   897        ;
   898      }
   899      break;
   900    case COAP_SIGNALING_ABORT:
   901      switch (pdu->max_opt) {
   902      case COAP_SIGNALING_OPTION_BAD_CSM_OPTION:
   903        if (len > 2) goto bad;
   904        break;
   905      default:
   906        ;
   907      }
   908      break;
   909    default:
   910      ;
   911    }
   912    return 1;
   913  bad:
   914    return 0;
   915  }
