   932    case COAP_OPTION_MAXAGE:        if (len > 4) res = 0;               break;
   933    case COAP_OPTION_URI_QUERY:     if (len < 1 || len > 255) res = 0;  break;
   934    case COAP_OPTION_HOP_LIMIT:     if (len != 1) res = 0;              break;
   935    case COAP_OPTION_ACCEPT:        if (len > 2) res = 0;               break;
   936    case COAP_OPTION_LOCATION_QUERY:if (len > 255) res = 0;             break;
