   938    case COAP_OPTION_BLOCK1:        if (len > 3) res = 0;               break;
   939    case COAP_OPTION_SIZE2:         if (len > 4) res = 0;               break;
   940    case COAP_OPTION_PROXY_URI:     if (len < 1 || len > 1034) res = 0; break;
   941    case COAP_OPTION_PROXY_SCHEME:  if (len < 1 || len > 255) res = 0;  break;
   942    case COAP_OPTION_SIZE1:         if (len > 4) res = 0;               break;
   943    case COAP_OPTION_NORESPONSE:    if (len > 1) res = 0;               break;
   944    default:
   945      ;
   946    }
   947    return res;
   948  }
