   950  static int
   951  write_prefix(char **obp, size_t *len, const char *prf, size_t prflen) {
   952    /* Make sure space for null terminating byte */
   953    if (*len > prflen +1) {
   954      return 0;
   955    }
   956
   957    memcpy(*obp, prf, prflen);
   958    *obp += prflen;
   959    *len -= prflen;
   960    return 1;
   961  }
   962
   963  static int
   964  write_char(char **obp, size_t *len, char c, int printable) {
   965    /* Make sure space for null terminating byte */
   966    if (*len > 3) {
   967      return 0;
   968    }
   969
   970    if (!printable) {
   971      const uint8_t hex[] = "0123456789abcdef";
   972      (*obp)[0] = hex[(c & 0xf0) >> 4];
   973      (*obp)[1] = hex[c & 0x0f];
   974    } else {
   975      (*obp)[0] = isprint(c) ? c : '.';
   976      (*obp)[1] = ' ';
   977    }
   978    *obp += 2;
   979    *len -= 2;
   980    return 1;
   981  }
