   983  int
   984  coap_pdu_parse_opt(coap_pdu_t *pdu) {
   985
   986    int good = 1;
   987    /* sanity checks */
   988    if (pdu->code == 0) {
   989      if (pdu->used_size != 0 || pdu->token_length) {
   990        coap_log(LOG_DEBUG, "coap_pdu_parse: empty message is not empty\n");
   991        return 0;
   992      }
   993    }
   994
   995    if (pdu->token_length > pdu->used_size || pdu->token_length > 8) {
   996      coap_log(LOG_DEBUG, "coap_pdu_parse: invalid Token\n");
   997      return 0;
   998    }
   999
  1000    pdu->max_opt = 0;
  1001    if (pdu->code == 0) {
  1002      /* empty packet */
  1003      pdu->used_size = 0;
  1004      pdu->data = NULL;
  1005    } else {
  1006      /* skip header + token */
  1007      coap_opt_t *opt = pdu->token + pdu->token_length;
  1008      size_t length = pdu->used_size - pdu->token_length;
  1009
  1010      while (length > 0 && *opt != COAP_PAYLOAD_START) {
  1011        coap_opt_t *opt_last = opt;
  1012        size_t optsize = next_option_safe(&opt, &length, &pdu->max_opt);
  1013        const uint32_t len =
  1014          optsize ? coap_opt_length((const uint8_t *)opt - optsize) : 0;
  1015        if (optsize == 0) {
  1016          coap_log(LOG_DEBUG,
  1017              "coap_pdu_parse: %d.%02d: offset %u malformed option\n",
  1018                 pdu->code >> 5, pdu->code & 0x1F,
  1019                 (int)(opt_last - pdu->token - pdu->token_length));
  1020          good = 0;
  1021          break;
  1022        }
  1023        if (COAP_PDU_IS_SIGNALING(pdu) ?
  1024             !coap_pdu_parse_opt_csm(pdu, len) :
  1025             !coap_pdu_parse_opt_base(pdu, len)) {
  1026          coap_log(LOG_WARNING,
  1027              "coap_pdu_parse: %d.%02d: offset %u option %u has bad length %u\n",
  1028                   pdu->code >> 5, pdu->code & 0x1F,
  1029                   (int)(opt_last - pdu->token - pdu->token_length), pdu->max_opt,
  1030                   len);
  1031          good = 0;
  1032        }
  1033      }
  1034
  1035      if (!good) {
  1036        /*
  1037         * Dump the options in the PDU for analysis, space separated except
  1038         * error options which are prefixed by *
  1039         * Two rows - hex and ascii (if printable)
  1040         */
  1041        static char outbuf[COAP_DEBUG_BUF_SIZE];
  1042        char *obp;
  1043        size_t tlen;
  1044        size_t outbuflen;
  1045        int i;
  1046        int ok;
  1047
  1048        for (i = 0; i < 2; i++) {
  1049          opt = pdu->token + pdu->token_length;
  1050          length = pdu->used_size - pdu->token_length;
  1051          pdu->max_opt = 0;
  1052
  1053          outbuflen = sizeof(outbuf);
  1054          obp = outbuf;
  1055          ok = write_prefix(&obp, &outbuflen, "O: ", 3);
  1056          while (length > 0 && *opt != COAP_PAYLOAD_START) {
  1057            coap_opt_t *opt_last = opt;
  1058            size_t optsize = next_option_safe(&opt, &length, &pdu->max_opt);
  1059            const uint32_t len =
  1060              optsize ? coap_opt_length((const uint8_t *)opt - optsize) : 0;
  1061            if (!optsize || (COAP_PDU_IS_SIGNALING(pdu) ?
  1062                 !coap_pdu_parse_opt_csm(pdu, len) :
  1063                 !coap_pdu_parse_opt_base(pdu, len))) {
  1064              ok = ok && write_prefix(&obp, &outbuflen, "*", 1);
  1065              if (!optsize) {
  1066                /* Skip to end of options to output all data */
  1067                opt = pdu->token + pdu->used_size;
  1068                length = 0;
  1069              }
  1070            }
  1071            else {
  1072              ok = ok && write_prefix(&obp, &outbuflen, " ", 1);
  1073            }
  1074            tlen = opt - opt_last;
  1075            while (tlen--) {
  1076              ok = ok && write_char(&obp, &outbuflen, *opt_last, i);
  1077              opt_last++;
  1078            }
  1079          }
  1080          if (length && *opt == COAP_PAYLOAD_START) {
  1081            ok = ok && write_char(&obp, &outbuflen, *opt, i);
  1082          }
  1083          /* write_*() always leaves a spare byte to null terminate */
  1084          *obp = '\000';
  1085          coap_log(LOG_DEBUG, "%s\n", outbuf);
  1086        }
  1087      }
  1088
  1089      if (length > 0) {
  1090        assert(*opt == COAP_PAYLOAD_START);
  1091        opt++; length--;
  1092
  1093        if (length == 0) {
  1094          coap_log(LOG_DEBUG,
  1095                   "coap_pdu_parse: message ending in payload start marker\n");
  1096          return 0;
  1097        }
  1098      }
  1099      if (length > 0)
  1100        pdu->data = (uint8_t*)opt;
  1101      else
  1102        pdu->data = NULL;
  1103    }
  1104
  1105    return good;
  1106  }
