   214  uint32_t
   215  coap_opt_length(const coap_opt_t *opt) {
   216    uint32_t length;
   217
   218    length = *opt & 0x0f;
   219    switch (*opt & 0xf0) {
   220    case 0xf0:
   221      coap_log(LOG_DEBUG, "illegal option delta\n");
   222      return 0;
   223    case 0xe0:
   224      ++opt;
   225      /* fall through */
   226      /* to skip another byte */
   227    case 0xd0:
   228      ++opt;
   229      /* fall through */
   230      /* to skip another byte */
   231    default:
   232      ++opt;
   233    }
   234
   235    switch (length) {
   236    case 0x0f:
   237      coap_log(LOG_DEBUG, "illegal option length\n");
   238      return 0;
   239    case 0x0e:
   240      length = (*opt++ << 8) + 269;
   241      /* fall through */
   242    case 0x0d:
   243      length += *opt++;
   244      break;
   245    default:
   246      ;
   247    }
   248    return length;
   249  }
